const DONGHUA_ATLAS = "data:image/jpeg;base64,";
function decorateDonghuaThumbnail(el, style) {
  el.style.display='block'; el.style.aspectRatio='1'; el.style.width='100%';
  el.style.backgroundImage='url("'+DONGHUA_ATLAS+'")';
  el.style.backgroundSize='200% 500%';
  el.style.backgroundPosition=(style.previewTile%2*100)+'% '+(Math.floor(style.previewTile/2)*25)+'%';
  el.style.backgroundRepeat='no-repeat';
  el.setAttribute('aria-hidden','true');
}
